import org.jsoup.parser.XmlTreeBuilder;
import org.junit.jupiter.api.Test;

public class XmlTreeBuilderTest {

    @Test
    public void testDefaultSettings() {
        String baseUri = "http://example.com";
        ParseSettings defaultSettings = new XmlTreeBuilder().defaultSettings();
        assert defaultSettings.getBaseUri() == baseUri;
        assert !defaultSettings.isValidateXml();
    }

    @Test
    public void testParse() {
        Document document = new XmlTreeBuilder().parse(new StringReader("<root><a>b</a></root>"));
        Document expectedDocument = new XmlTreeBuilder().parse("http://example.com/root.html", "http://example.com");
        Assert.assertSame(document, expectedDocument);
    }

    @Test
    public void testParseFragment() {
        List<Node> nodes = new XmlTreeBuilder().parseFragment("<a><b/>c</b></a>", "http://example.com", new XmlTreeBuilder());
        Assert.assertTrue(nodes.contains(new Node(Element.Tag("root"), new CDataNode(), new Comment(), new Token.StartTag("a"), new Token.StopTag())));
    }

    @Test
    public void testParseFragmentWithToken() {
        List<Node> nodes = new XmlTreeBuilder().parseFragment("<a><b/>c</b></a>", "http://example.com", new XmlTreeBuilder());
        Assert.assertTrue(nodes.contains(new Node(Element.Tag("root"), new CDataNode(), new Comment(), new Token.StartTag("a"), new Token.StopTag())));
    }

    @Test
    public void testParseFragmentWithTokenAndBaseUri() {
        List<Node> nodes = new XmlTreeBuilder().parseFragment("<a><b/>c</b></a>", "http://example.com", "http://example.com");
        Assert.assertTrue(nodes.contains(new Node(Element.Tag("root"), new CDataNode(), new Comment(), new Token.StartTag("a"), new Token.StopTag())));
    }

    @Test
    public void testInsertNode() {
        XmlTreeBuilder builder = new XmlTreeBuilder();
        Document document = builder.parse(new StringReader("<root><a>b</a></root>"));
        Node root = document.getElementsByTagName("root").item(0);
        builder.insert(root, new Token.Comment("new comment", "comment_text"));
        Assert.assertTrue(root.getTextContent().equals("new comment comment_text"));
    }

    @Test
    public void testInsertNodeWithToken() {
        XmlTreeBuilder builder = new XmlTreeBuilder();
        Document document = builder.parse(new StringReader("<root><a>b</a></root>"));
        Node root = document.getElementsByTagName("root").item(0);
        builder.insert(root, new Token.StartTag("a"));
        Assert.assertTrue(root.getTextContent().equals("a b"));
    }

